```cpp
// (1) per-block partial sums, last block finishes the reduction
__global__ void bias_grad(const float* dout, float* partial, unsigned* flag, float* dbias, int N, int C) {
  extern __shared__ float acc[];            // C floats
  for (int c = threadIdx.x; c < C; c += blockDim.x) acc[c] = 0.f;
  __syncthreads();
  for (int r = blockIdx.x; r < N; r += gridDim.x)
    for (int c = threadIdx.x; c < C; c += blockDim.x) acc[c] += dout[r * C + c];
  __syncthreads();
  for (int c = threadIdx.x; c < C; c += blockDim.x) partial[blockIdx.x * C + c] = acc[c];
  __syncthreads();
  __shared__ unsigned last;
  if (threadIdx.x == 0) last = atomicInc(flag, gridDim.x);
  __syncthreads();
  if (last == gridDim.x - 1)
    for (int c = threadIdx.x; c < C; c += blockDim.x) {
      float s = 0.f;
      for (int b = 0; b < gridDim.x; b++) s += partial[b * C + c];
      dbias[c] = s;
    }
}

