// tuning.cuh
__device__ static constexpr cuda::std::array<double, 6> bias_p4{10.0, 9.717, 9.207, 8.789, 8.288, 7.820};
__device__ static constexpr cuda::std::array<double, 6> raw_p4{11.0, 11.717, 12.207, 12.79, 13.288, 13.82};

__host__ __device__ constexpr double const* bias_data(int p) noexcept { return p == 4 ? bias_p4.data() : nullptr; }
__host__ __device__ constexpr double const* raw_data(int p) noexcept { return p == 4 ? raw_p4.data() : nullptr; }

// finalizer.cuh -- runs on the HOST after the sketch is copied back
struct finalizer {
  int precision_;
  __host__ __device__ double correct(double e) const {
    auto raw = raw_data(precision_);
    auto bias = bias_data(precision_);
    int i = 0;
    while (i < 5 && raw[i] < e) ++i;
    return e - bias[i];
  }
};
